39	// The key comes from STRIPE_SECRET_KEY, else from the file named by STRIPE_ENV, else from .env at
40	// the repository root (git-ignored).
41	export function testKey(): string {
42	  const file = process.env.STRIPE_ENV ?? join(import.meta.dirname, "..", "..", ".env");
43	  const fromFile = existsSync(file)
44	    ? /STRIPE_SECRET_KEY=(\S+)/.exec(readFileSync(file, "utf8"))?.[1]
45	    : undefined;
46	  const key = process.env.STRIPE_SECRET_KEY ?? fromFile;
47	  // Invariant 4: never record outside test mode.
48	  if (key?.startsWith("sk_test_") !== true) {
49	    throw new Error("refusing: STRIPE_SECRET_KEY is missing or not a test key (see .env.example)");
50	  }
51	  return key;
52	}
