54	export function client(side: Side): Stripe {
55	  if (side.kind === "target") return new Stripe(testKey(), { maxNetworkRetries: 2 });
56	  const url = new URL(side.url);
57	  return new Stripe("sk_test_clone", {
58	    host: url.hostname,
59	    port: Number(url.port),
60	    protocol: "http",
61	  });
