75	async function couponId(stripe: Stripe, c: z.infer<typeof Coupon>): Promise<string> {
76	  const created = await stripe.coupons.create({
77	    duration: c.duration,
78	    ...(c.percent_off !== undefined ? { percent_off: c.percent_off } : {}),
79	    ...(c.amount_off !== undefined ? { amount_off: c.amount_off, currency: "usd" } : {}),
80	  });
81	  return created.id;
