67	// always_invoice: the pending items are invoiced at once and the payment attempted (PRO-07).
68	export function invoiceNow(state: State, sub: Subscription, now: number): Invoice {
69	  const id = mint(state, "in");
70	  const lines = takePending(state, sub, id);
71	  const inv: Invoice = {
72	    id,
73	    customer: sub.customer,
74	    subscription: sub.id,
75	    lines,
76	    discounts: [],
77	    total_discount_amounts: [],
78	    billing_reason: "subscription_update",
79	    status: "draft",
80	    created: now,
81	    period_start: now,
82	    period_end: now,
83	    attempt_count: 0,
84	    amount_paid: 0,
85	    auto_advance: true,
86	    next_payment_attempt: now,
87	    proration_date: null,
88	    retries: [],
89	    starting_balance: 0,
90	    deferred: 0,
91	  };
92	  const cus = get(state.customers, sub.customer);
93	  if (cus) {
94	    inv.starting_balance = cus.balance;
95	    cus.balance = Math.min(0, invoiceTotal(inv) + cus.balance);
96	  }
97	  state.invoices[id] = inv;
98	  sub.latest_invoice = id;
99	  attempt(state, inv, now);
100	  return inv;
101	}
