270	export function cancelNow(
271	  state: State,
272	  sub: Subscription,
273	  prorate: boolean,
274	  invoiceNow: boolean,
275	): void {
276	  const now = nowFor(state, sub.customer);
277	  if (prorate && now < sub.period_end) {
278	    const credits = sub.items.map((it) => creditLine(state, sub, it, now).line);
279	    if (invoiceNow) {
280	      const id = mint(state, "in");
281	      const pending = takePending(state, sub, id);
282	      const lines: Line[] = [
283	        ...pending,
284	        ...credits.map((l) => ({ ...l, id: mint(state, "il"), invoice_item: mint(state, "ii") })),
285	      ];
286	      state.invoices[id] = {
287	        id,
288	        customer: sub.customer,
289	        subscription: sub.id,
290	        lines,
291	        discounts: [],
292	        total_discount_amounts: [],
293	        billing_reason: "subscription_cycle",
294	        status: "draft",
295	        created: now,
296	        period_start: sub.period_start,
297	        period_end: now,
298	        attempt_count: 0,
299	        amount_paid: 0,
300	        auto_advance: false,
301	        next_payment_attempt: null,
302	        proration_date: null,
303	        retries: [],
304	        starting_balance: 0,
305	        deferred: 0,
306	      };
307	      sub.latest_invoice = id;
308	    } else {
309	      for (const l of credits) addPending(state, sub, l, now);
310	    }
311	  }
312	  sub.status = "canceled";
313	  sub.ended_at = now;
314	  sub.canceled_at ??= now;
315	  sub.cancellation_reason = "cancellation_requested";
316	  sub.cancel_at_period_end = false;
317	  sub.cancel_at = null;
318	}
