1	/**
2	 * Slice 2: the subscription lifecycle over time. A lifecycle probe is a script of actions on one
3	 * subscription living on a test clock (cancel at period end, reactivate, cancel now, advance the
4	 * clock, swap in a failing card), with a snapshot of the subscription and its latest invoice after
5	 * the steps that matter. Snapshots are a projection: fields outside it are not compared.
6	 */
7	import Stripe from "stripe";
8	import { z } from "zod";
9	import { JsonSchema, type Json } from "../../harness/src/json.ts";
10	import { Coupon, couponId } from "./wide.ts";
11	
12	export const LifeStep = z.discriminatedUnion("do", [
13	  z.object({ do: z.literal("cancel_at_period_end") }),
14	  z.object({ do: z.literal("reactivate") }),
15	  z.object({ do: z.literal("cancel_now"), prorate: z.boolean(), invoice_now: z.boolean() }),
16	  z.object({ do: z.literal("advance"), seconds: z.number() }),
17	  z.object({ do: z.literal("failing_card") }),
18	  // Swaps the failing card for a working one, to see a past_due subscription recover.
19	  z.object({ do: z.literal("good_card") }),
20	  z.object({ do: z.literal("snapshot"), as: z.string() }),
21	  // Reads a subscription that does not exist, to pin the error a missing object returns.
22	  z.object({ do: z.literal("retrieve_missing"), as: z.string() }),
23	  // Any API call, recorded whole: replays the calls an agent made in task validation. Path and
24	  // parameter values may name {subscription}, {customer}, {item}, {price}, {price2}, {coupon},
25	  // {period_end} (the first period's end), and {<as>.id}, the id an earlier raw step returned.
26	  z.object({
27	    do: z.literal("raw"),
28	    as: z.string(),
29	    method: z.enum(["GET", "POST", "DELETE"]),
30	    path: z.string(),
31	    params: z.record(z.string(), z.string()).default({}),
32	  }),
33	]);
34	export type LifeStep = z.infer<typeof LifeStep>;
35	
36	export const LifeInput = z.object({
37	  kind: z.literal("lifecycle"),
38	  start: z.number(),
39	  amount: z.number(),
40	  trial_days: z.number().nullable(),
41	  // A coupon on the subscription from its creation; absent in fixtures recorded before it existed.
42	  coupon: Coupon.nullable().default(null),
43	  // A second monthly price ("Pro") to move to, for raw calls; absent in older fixtures.
44	  second_amount: z.number().nullable().default(null),
45	  // A coupon created but not applied, for raw calls to apply ({coupon}); absent in older fixtures.
46	  spare_coupon: Coupon.nullable().default(null),
47	  steps: z.array(LifeStep),
48	});
49	export type LifeInput = z.infer<typeof LifeInput>;
50	
51	export function invoiceView(inv: Stripe.Invoice | null): Json {
52	  if (!inv) return null;
53	  return {
54	    status: inv.status ?? null,
55	    billing_reason: inv.billing_reason ?? null,
56	    subtotal: inv.subtotal,
57	    total: inv.total,
58	    amount_due: inv.amount_due,
59	    amount_paid: inv.amount_paid,
60	    amount_remaining: inv.amount_remaining,
61	    attempt_count: inv.attempt_count,
62	    period_start: inv.period_start,
63	    period_end: inv.period_end,
64	    lines: inv.lines.data.map((l) => ({ amount: l.amount, description: l.description ?? null })),
65	  };
66	}
67	
68	function refId(v: Json | undefined): string | null {
69	  if (typeof v !== "object" || v === null || Array.isArray(v)) return null;
70	  const body = v.body;
71	  if (typeof body !== "object" || body === null || Array.isArray(body)) return null;
72	  return typeof body.id === "string" ? body.id : null;
73	}
74	
75	async function waitReady(stripe: Stripe, clock: string): Promise<void> {
76	  for (let i = 0; i < 60; i += 1) {
77	    const c = await stripe.testHelpers.testClocks.retrieve(clock);
78	    if (c.status === "ready") return;
79	    await new Promise((r) => setTimeout(r, 1000));
80	  }
81	  throw new Error(`test clock ${clock} did not become ready`);
82	}
83	
84	export async function runLifecycle(
85	  stripe: Stripe,
86	  input: LifeInput,
87	): Promise<Record<string, Json>> {
