import { loadAdapter } from "/work/harness/src/adapter.ts";
import { loadFixtures, targetDir } from "/work/harness/src/fixtures.ts";
import { diff, PolicySchema } from "/work/harness/src/policy.ts";

const target = "stripe-billing";
const prefix = process.argv[2] ?? "dev-v4-";
const max = Number(process.argv[3] ?? "60");
const dump = process.argv[4] === "dump";
const policy = PolicySchema.parse(
  JSON.parse(readFileSync(join(targetDir(target), "policy.json"), "utf8")),
);
const adapter = await loadAdapter(target);
const clone = await startCloneProcess(target, adapter.cloneEntry, 4611);
try {
  for (const f of loadFixtures(target, ["dev"]).filter((x) => x.id.startsWith(prefix))) {
    await fetch(`${clone.url}/__reset`, { method: "POST" });
    const actual = await adapter.run(f, { kind: "clone", url: clone.url });
    if (dump) console.log(JSON.stringify(actual, null, 1));
    const d = diff(
      { ...policy, fields: [...policy.fields, ...f.noise.map((path) => ({ path, mode: "ignore" as const, why: "noise" }))] },
      f.observed,
      actual,
    );
    console.log(`== ${f.id}: ${d.length}`);
    for (const x of d.slice(0, max)) {
      console.log(`   ${x.path}: ${JSON.stringify(x.expected)} => ${JSON.stringify(x.actual)}`);
    }
  }
} finally {
  await clone.close();
}

