108	export function billFirstInvoice(state: State, sub: Subscription, now: number): Invoice {
109	  const id = mint(state, "in");
110	  const trial = sub.status === "trialing";
111	  const specs = trial ? [] : specsOf(state, sub.discounts);
112	  const lines: Line[] = sub.items.map((it) => {
113	    const p = priceOf(state, it.price);
114	    return {
115	      id: mint(state, "il"),
116	      amount: trial ? 0 : p.unit_amount * it.quantity,
117	      description: trial
118	        ? `Free trial for ${it.quantity} × ${productName(state, it.price)}`
119	        : recurringDescription(state, it.price, it.quantity),
120	      period: { start: sub.period_start, end: sub.period_end },
121	      price: it.price,
122	      quantity: it.quantity,
123	      proration: false,
124	      discountable: true,
125	      discount_amounts: [],
126	      subscription_item: it.id,
127	      invoice_item: null,
128	      credited: null,
129	      unit_amount_decimal: String(p.unit_amount),
130	    };
131	  });
132	  const alloc = allocate(
133	    lines.map((l) => l.amount),
134	    specs,
135	  );
136	  lines.forEach((l, i) => {
137	    l.discount_amounts = specs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
138	  });
139	  sub.items.forEach((it, i) => {
140	    const l = lines[i];
141	    if (l) it.billed = { invoice: id, line: l.id, amount: l.amount, discounts: l.discount_amounts };
142	  });
143	  spendOnce(state, specs, alloc);
144	  const tda = specs.map((s, k) => ({
145	    discount: s.id,
146	    amount: (alloc[k] ?? []).reduce((a, b) => a + b, 0),
147	  }));
148	  const inv: Invoice = {
149	    id,
150	    customer: sub.customer,
151	    subscription: sub.id,
152	    lines,
153	    discounts: specs.map((s) => s.id),
154	    total_discount_amounts: tda,
155	    billing_reason: "subscription_create",
156	    status: "paid",
157	    created: now,
158	    period_start: now,
159	    period_end: now,
160	    attempt_count: 0,
161	    amount_paid: 0,
162	    auto_advance: false,
163	    next_payment_attempt: null,
164	    proration_date: null,
165	    retries: [],
166	    starting_balance: 0,
167	    deferred: 0,
168	  };
169	  if (!deferSmall(state, inv)) {
170	    const due = amountDue(inv);
171	    inv.amount_paid = due;
172	    inv.attempt_count = due > 0 ? 1 : 0;
173	  }
174	  state.invoices[id] = inv;
175	  sub.latest_invoice = id;
176	  return inv;
177	}
