234	function previewInvoice(state: State, p: Params): CloneResponse {
235	  const subId = str(p.subscription) ?? "";
236	  const sub = get(state.subscriptions, subId);
237	  if (!sub) return missing("subscription", subId);
238	  const details = obj(p.subscription_details);
239	  const changes: ItemChange[] = arr(details.items).map((raw) => {
240	    const it = obj(raw);
241	    return { id: str(it.id) ?? "", price: str(it.price), quantity: num(it.quantity) };
242	  });
243	  const now = nowFor(state, sub.customer);
244	  const discounts =
245	    p.discounts !== undefined
246	      ? arr(p.discounts).map(
247	          (raw) => newDiscount(state, str(obj(raw).coupon) ?? "", sub.customer, null, now).id,
248	        )
249	      : null;
250	  const behavior = str(details.proration_behavior) as Behavior | null;
251	  const plan = planChange(state, sub, {
252	    changes,
253	    proration_date: num(details.proration_date),
254	    behavior,
255	    discounts,
256	    now,
257	  });
258	  if (isPlanError(plan)) return fail(400, plan.message, plan.param);
259	  // Pending invoice items of the subscription (earlier changes) come first, as they are.
260	  const pending: Line[] = pendingItems(state, sub).map((ii) => ({
261	    ...ii.line,
262	    id: mint(state, "il_tmp"),
263	    invoice_item: ii.id,
264	  }));
265	  const draft = draftFromPlan(
266	    state,
267	    sub,
268	    plan,
269	    { line: () => mint(state, "il_tmp"), item: () => mint(state, "ii") },
270	    sub.billing_mode,
271	  );
272	  const inv: Invoice = {
273	    id: mint(state, "upcoming_in"),
274	    customer: sub.customer,
275	    subscription: sub.id,
276	    lines: [...pending, ...draft.lines],
277	    discounts: draft.discounts,
278	    total_discount_amounts: draft.total_discount_amounts,
279	    billing_reason: "upcoming",
280	    status: "draft",
281	    created: draft.created,
282	    period_start: draft.period_start,
283	    period_end: draft.period_end,
284	    attempt_count: 0,
285	    amount_paid: 0,
286	    auto_advance: !draft.immediate,
287	    next_payment_attempt: draft.immediate ? null : draft.created + 3600,
288	    proration_date: num(details.proration_date) !== null ? plan.proration_date : null,
289	    retries: [],
290	    starting_balance: get(state.customers, sub.customer)?.balance ?? 0,
291	    deferred: 0,
292	  };
293	  return ok(invoiceJson(state, inv, true));
294	}
295	
296	function pendingItems(state: State, sub: Subscription) {
297	  return Object.values(state.invoice_items).filter(
298	    (ii) => ii.subscription === sub.id && ii.invoice === null,
299	  );
300	}
301	
302	const BEHAVIORS = ["create_prorations", "none", "always_invoice"];
303	
304	// A change of items made for real (POST subscription or subscription item): the prorations become
305	// pending invoice items (create_prorations), an invoice now (always_invoice), or nothing (none).
306	function applyChange(
307	  state: State,
308	  sub: Subscription,
309	  changes: ItemChange[],
310	  p: Params,
311	): CloneResponse | null {
312	  const raw = str(p.proration_behavior);
313	  const behavior = raw !== null && BEHAVIORS.includes(raw) ? (raw as Behavior) : null;
314	  const now = nowFor(state, sub.customer);
315	  const plan = planChange(state, sub, {
316	    changes,
317	    proration_date: num(p.proration_date),
318	    behavior,
319	    discounts: null,
320	    now,
321	  });
322	  if (isPlanError(plan)) return fail(400, plan.message, plan.param);
323	  for (const l of plan.prorations) addPending(state, sub, l, now);
324	  sub.items.forEach((it) => {
325	    const next = plan.items.find((x) => x.id === it.id);
326	    if (next) {
327	      it.price = next.price;
328	      it.quantity = next.quantity;
329	    }
330	  });
331	  if (plan.reset) {
332	    sub.anchor = plan.anchor;
333	    sub.period_start = plan.period_start;
334	    sub.period_end = plan.period_end;
335	  }
336	  if (plan.immediate) invoiceNow(state, sub, now);
337	  return null;
338	}
