340	const LEGACY_COUPON =
341	  "With `billing_mode.type=flexible` set on a subscription, the following parameters are not supported: coupon.";
342	
343	function updateSubscription(state: State, sub: Subscription, p: Params): CloneResponse {
344	  const now = nowFor(state, sub.customer);
345	  if (p.coupon !== undefined && sub.billing_mode === "flexible") {
346	    return fail(400, LEGACY_COUPON);
347	  }
348	  const coupons: string[] | null =
349	    p.discounts !== undefined
350	      ? arr(p.discounts).map((raw) => str(obj(raw).coupon) ?? "")
351	      : p.coupon !== undefined
352	        ? [str(p.coupon) ?? ""].filter((c) => c !== "")
353	        : null;
354	  if (coupons) {
355	    for (const c of coupons) if (!get(state.coupons, c)) return missing("coupon", c);
356	  }
357	  if (p.items !== undefined) {
358	    const changes: ItemChange[] = arr(p.items).map((raw) => {
359	      const it = obj(raw);
360	      return { id: str(it.id) ?? "", price: str(it.price), quantity: num(it.quantity) };
361	    });
362	    for (const ch of changes) {
363	      if (!sub.items.some((it) => it.id === ch.id)) return missing("subscription_item", ch.id);
364	      if (ch.price !== null && !get(state.prices, ch.price)) return missing("price", ch.price);
365	    }
366	    const failed = applyChange(state, sub, changes, p);
367	    if (failed) return failed;
368	  }
369	  if (coupons) {
370	    sub.discounts = coupons.map((c) => newDiscount(state, c, sub.customer, sub.id, now).id);
371	  }
372	  if (p.cancel_at_period_end !== undefined) {
373	    const on = bool(p.cancel_at_period_end);
374	    sub.cancel_at_period_end = on;
375	    sub.cancel_at = on ? sub.period_end : null;
376	    sub.canceled_at = on ? now : null;
377	    sub.cancellation_reason = on ? "cancellation_requested" : null;
378	  }
379	  return ok(subscriptionJson(state, sub, false));
380	}
381	
382	function findItem(state: State, id: string): { sub: Subscription; it: SubItem } | null {
383	  for (const sub of Object.values(state.subscriptions)) {
384	    const it = sub.items.find((x) => x.id === id);
385	    if (it) return { sub, it };
386	  }
387	  return null;
388	}
389	
390	function subscriptionItems(state: State, req: CloneRequest, p: Params, id?: string): CloneResponse {
391	  if (id === undefined) {
392	    if (req.method !== "GET") return fail(400, "Missing required param: subscription.");
393	    const subId = str(p.subscription) ?? "";
394	    const sub = get(state.subscriptions, subId);
395	    if (!sub) return missing("subscription", subId);
396	    return ok({
397	      object: "list",
398	      data: sub.items.map((it) => itemJson(state, sub, it)),
399	      has_more: false,
400	      url: `/v1/subscription_items?subscription=${sub.id}`,
401	    });
402	  }
403	  const found = findItem(state, id);
404	  if (!found) return missing("subscription_item", id);
405	  const { sub, it } = found;
406	  if (req.method === "POST") {
407	    const price = str(p.price);
408	    if (price !== null && !get(state.prices, price)) return missing("price", price);
409	    const failed = applyChange(state, sub, [{ id: it.id, price, quantity: num(p.quantity) }], p);
410	    if (failed) return failed;
411	  }
412	  return ok(itemJson(state, sub, it));
413	}
414	
415	function listSubscriptions(state: State, q: Params): CloneResponse {
416	  const customer = str(q.customer);
417	  const status = str(q.status);
418	  const limit = num(q.limit) ?? 10;
419	  const all = Object.values(state.subscriptions)
420	    .filter((s) => customer === null || s.customer === customer)
421	    .filter((s) =>
422	      status === null ? s.status !== "canceled" : status === "all" || s.status === status,
423	    )
424	    .reverse()
425	    .slice(0, limit);
426	  return ok({
427	    object: "list",
428	    data: all.map((s) => subscriptionJson(state, s, false)),
429	    has_more: false,
430	    url: "/v1/subscriptions",
431	  });
432	}
433	
434	const UPCOMING_GONE =
435	  "This API method has been deprecated. Please use the Create Preview Invoice API instead: https://docs.stripe.com/api/invoices/create_preview.";
436	
437	function listInvoices(state: State, q: Params): CloneResponse {
438	  const sub = str(q.subscription);
439	  const limit = num(q.limit) ?? 10;
440	  const all = Object.values(state.invoices)
441	    .filter((i) => sub === null || i.subscription === sub)
442	    .reverse()
443	    .slice(0, limit);
444	  return ok({
445	    object: "list",
446	    data: all.map((i) => invoiceJson(state, i, false)),
447	    has_more: false,
448	    url: "/v1/invoices",
449	  });
450	}
451	
452	function listInvoiceItems(state: State, q: Params): CloneResponse {
453	  const customer = str(q.customer);
454	  const pending = bool(q.pending);
455	  // Newest first by date; items of the same date in creation order (dev-ag-*: credit, then
456	  // charge).
457	  const items = Object.values(state.invoice_items)
458	    .filter((i) => customer === null || i.customer === customer)
459	    .filter((i) => !pending || i.invoice === null)
460	    .map((i, k) => ({ i, k }))
461	    .sort((a, b) => b.i.date - a.i.date || a.k - b.k)
462	    .map((x) => x.i);
463	  return ok({
464	    object: "list",
465	    data: items.map((i) => invoiceItemJson(state, i)),
466	    has_more: false,
467	    url: "/v1/invoiceitems",
468	  });
469	}
