593	// An 8-letter invoice prefix, deterministic (recorded as noise).
594	function invoicePrefix(n: number): string {
595	  let x = n * 2654435761;
596	  let s = "";
597	  for (let i = 0; i < 8; i += 1) {
598	    s += String.fromCharCode(65 + (x % 26));
599	    x = Math.floor(x / 26) + 7 * (i + 1);
600	  }
601	  return s;
602	}
603	
604	function clockJson(state: State, id: string): Json {
605	  const c = get(state.clocks, id);
606	  return {
607	    id,
608	    object: "test_helpers.test_clock",
609	    created: c?.created ?? 0,
610	    frozen_time: c?.frozen_time ?? 0,
611	    livemode: false,
612	    status: "ready",
613	  };
614	}
